const arr = [1, [2, [3, [4]]]];
function deepFlatten(arr) {
  return arr.reduce((acc, val) =>
    acc.concat(Array.isArray(val) ? deepFlatten(val) : val), []);
}
console.log(deepFlatten(arr));
